import{_ as t,o as c,c as o,a2 as a}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"Block, Item & NBT Predicates and Probability Models","description":"","frontmatter":{},"headers":[],"relativePath":"en/1.21.4/util/predicates.md","filePath":"en/1.21.4/util/predicates.md"}'),d={name:"en/1.21.4/util/predicates.md"};function i(r,e,n,l,s,h){return c(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="block-item-nbt-predicates-and-probability-models" tabindex="-1">Block, Item &amp; NBT Predicates and Probability Models <a class="header-anchor" href="#block-item-nbt-predicates-and-probability-models" aria-label="Permalink to &quot;Block, Item &amp; NBT Predicates and Probability Models&quot;">​</a></h1><p><code>dev.anvilcraft.lib.v2.util.predicate</code> provides a suite of <strong>data structures and state matchers</strong> with complete <code>Codec</code>, <code>StreamCodec</code>, and fluent builders, used directly by <code>module.recipe</code> and external recipe/rule systems as underlying condition and probabilistic output carriers.</p><h2 id="blockstate-blockentity-matching-blockstatepredicate" tabindex="-1">BlockState &amp; BlockEntity Matching: <code>BlockStatePredicate</code> <a class="header-anchor" href="#blockstate-blockentity-matching-blockstatepredicate" aria-label="Permalink to &quot;BlockState &amp; BlockEntity Matching: `BlockStatePredicate`&quot;">​</a></h2><p><code>BlockStatePredicate</code> can match block IDs/tags and <code>BlockState</code> properties (supporting exact values and numeric ranges <code>withMin</code> / <code>withMax</code> / <code>with(min, max)</code>), as well as bound <code>BlockEntity</code> NBT, including pure off-thread NBT checking.</p><h3 id="matching-execution-api" tabindex="-1">Matching Execution API <a class="header-anchor" href="#matching-execution-api" aria-label="Permalink to &quot;Matching Execution API&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>test(LevelAccessor level, BlockState state, @Nullable BlockEntity entity)</code></td><td>Full online check: matches block set and properties first, then compares entity NBT if <code>requiresBlockEntity()</code> is true</td></tr><tr><td><code>testWithoutEntity(BlockState state)</code></td><td>Checks only block and block properties</td></tr><tr><td><code>cannotMatch(BlockState state)</code></td><td>Fast negative pruning check</td></tr><tr><td><code>testEntity(LevelAccessor level, BlockState state, @Nullable BlockEntity entity)</code></td><td>Checks only the block entity&#39;s live NBT</td></tr><tr><td><code>testOffThread(BlockState state, @Nullable CompoundTag entityNbt)</code> / <code>testEntityOffThread(...)</code></td><td>Thread-safe off-thread version for multi-threaded recipe indexing or cache pre-filtering</td></tr><tr><td><code>requiresBlockEntity()</code></td><td>Whether this predicate has attached <code>CompoundTag</code> entity conditions</td></tr><tr><td><code>getStatesCache()</code> / <code>constructStatesForRender()</code></td><td>Returns all discrete <code>BlockState</code>s matching this predicate (the latter is used to cycle compatible blocks in recipe viewers)</td></tr><tr><td><code>getKey()</code></td><td>Extracts the canonical resource key for indexing (returns <code>BlockStatePredicate.EMPTY</code> if none)</td></tr></tbody></table><h3 id="blockstatepredicate-builder-construction-methods" tabindex="-1"><code>BlockStatePredicate.Builder</code> Construction Methods <a class="header-anchor" href="#blockstatepredicate-builder-construction-methods" aria-label="Permalink to &quot;`BlockStatePredicate.Builder` Construction Methods&quot;">​</a></h3><ul><li>Entry: <code>BlockStatePredicate.builder()</code></li><li>Specify block candidates: <code>of(Block... blocks)</code>, <code>of(Supplier&lt;? extends Block&gt;... blocks)</code>, <code>of(Collection&lt;Block&gt;)</code>, <code>of(TagKey&lt;Block&gt; tag)</code></li><li>Constrain block properties: <code>with(BlockState)</code>, <code>with(Property&lt;?&gt; prop, String val)</code>, <code>with(Property&lt;Integer&gt;, int)</code>, <code>with(Property&lt;Boolean&gt;, boolean)</code>, <code>with(Property&lt;T&gt;, T)</code>, ranges <code>with(Property&lt;T&gt;, Comparable, Comparable)</code> / <code>withMin(...)</code> / <code>withMax(...)</code></li><li>Multiple condition branches: <code>or()</code> (appends a new alternative matching branch)</li><li>Entity NBT: <code>nbt(CompoundTag tag)</code></li><li><code>build()</code> produces the immutable <code>BlockStatePredicate</code> (with built-in <code>CODEC</code> and <code>STREAM_CODEC</code>).</li></ul><h2 id="item-component-matching-iitemstackpredicate-itempredicate-itemingredientpredicate" tabindex="-1">Item &amp; Component Matching: <code>IItemStackPredicate</code>, <code>ItemPredicate</code> &amp; <code>ItemIngredientPredicate</code> <a class="header-anchor" href="#item-component-matching-iitemstackpredicate-itempredicate-itemingredientpredicate" aria-label="Permalink to &quot;Item &amp; Component Matching: `IItemStackPredicate`, `ItemPredicate` &amp; `ItemIngredientPredicate`&quot;">​</a></h2><p>Both support 1.21.4 registry tags <code>BuiltInRegistries.ITEM.getOrThrow(tag)</code>, item lists, count checks, <code>ItemSubPredicate</code> sub-predicates, and <code>DataComponentPredicate</code> data component matching.</p><table tabindex="0"><thead><tr><th>Class / Interface</th><th>Core Differences &amp; Usage</th></tr></thead><tbody><tr><td><code>IItemStackPredicate</code></td><td>Common item matching interface (declares <code>test(ItemStack)</code> and count check methods)</td></tr><tr><td><code>ItemPredicate</code></td><td>Constrains stack count with <code>MinMaxBounds.Ints</code> (supports ranges like <code>&gt;= 3</code>); provides <code>ItemPredicate.Builder.item().of(...).withCount(...).withSubPredicate(...).hasComponents(...).build()</code></td></tr><tr><td><code>ItemIngredientPredicate</code></td><td>Matcher designed for crafting-slot fixed counts (<code>ItemIngredientPredicate.of(...)</code> and <code>.withCount(int)</code>); also exposes <code>getItems()</code> (<code>ItemStack[]</code>) for recipe viewers</td></tr></tbody></table><p>Both expose <code>CODEC</code> and <code>STREAM_CODEC</code> constants (based on <code>StreamCodecUtil.codec2Stream</code>).</p><h2 id="lightweight-nbt-matching-nbtpredicate" tabindex="-1">Lightweight NBT Matching: <code>NbtPredicate</code> <a class="header-anchor" href="#lightweight-nbt-matching-nbtpredicate" aria-label="Permalink to &quot;Lightweight NBT Matching: `NbtPredicate`&quot;">​</a></h2><p><code>public record NbtPredicate(CompoundTag tag) implements Predicate&lt;Tag&gt;</code> (uses <code>TagParser.LENIENT_CODEC</code> for lenient SNBT):</p><ul><li><code>test(@Nullable Tag tag)</code>: recursive superset comparison (target NBT must contain all keys and matching values in expected <code>tag</code>, allowing extra undeclared fields);</li><li><code>test(ItemStack stack)</code> / <code>test(Entity entity)</code>: checks an item&#39;s custom NBT/component context or an entity&#39;s full saved data;</li><li><code>NbtPredicate.getEntityTagToCompare(Entity entity)</code>: extracts an entity NBT snapshot matching vanilla loot predicate semantics.</li></ul><h2 id="probabilistic-output-models-chanceblockstate-weightedchanceblockstates-chanceitemstack" tabindex="-1">Probabilistic Output Models: <code>ChanceBlockState</code>, <code>WeightedChanceBlockStates</code> &amp; <code>ChanceItemStack</code> <a class="header-anchor" href="#probabilistic-output-models-chanceblockstate-weightedchanceblockstates-chanceitemstack" aria-label="Permalink to &quot;Probabilistic Output Models: `ChanceBlockState`, `WeightedChanceBlockStates` &amp; `ChanceItemStack`&quot;">​</a></h2><p>Used to represent &quot;weighted random pick&quot; or &quot;probabilistic / dynamic <code>NumberProvider</code> count&quot; outcomes in recipes or world transformations (note: on <code>1.21.4</code>, evaluates <code>NumberProvider</code> via <code>new LootParams(level, ContextMap.EMPTY, Map.of(), 0)</code>).</p><h3 id="_1-chanceitemstack-itemstack-stack-numberprovider-count" tabindex="-1">1. <code>ChanceItemStack(ItemStack stack, NumberProvider count)</code> <a class="header-anchor" href="#_1-chanceitemstack-itemstack-stack-numberprovider-count" aria-label="Permalink to &quot;1. `ChanceItemStack(ItemStack stack, NumberProvider count)`&quot;">​</a></h3><ul><li>Factory methods: <ul><li><code>ChanceItemStack.of(ItemLike item, int count / NumberProvider amount)</code></li><li><code>ChanceItemStack.of(ItemStack stack[, int count[, float chance]][, NumberProvider amount / float chance])</code></li></ul></li><li>Runtime result &amp; metadata: <code>getResult(ServerLevel level)</code> (clamps <code>count</code> to <code>1..99</code> and returns a new <code>ItemStack</code> copy), <code>getItem()</code>, <code>getItemHolder()</code>, <code>getMaxCount()</code>, <code>getComponentsPatch()</code>.</li></ul><h3 id="_2-chanceblockstate-blockstate-state-compoundtag-nbt-numberprovider-chance" tabindex="-1">2. <code>ChanceBlockState(BlockState state, CompoundTag nbt, NumberProvider chance)</code> <a class="header-anchor" href="#_2-chanceblockstate-blockstate-state-compoundtag-nbt-numberprovider-chance" aria-label="Permalink to &quot;2. `ChanceBlockState(BlockState state, CompoundTag nbt, NumberProvider chance)`&quot;">​</a></h3><ul><li>Constructor overloads: <code>ChanceBlockState(state, chance)</code>, <code>ChanceBlockState(state, float)</code>, <code>ChanceBlockState.of(Supplier&lt;? extends Block&gt;[, CompoundTag nbt])</code>.</li><li>Runtime result: <code>@Nullable Map.Entry&lt;BlockState, CompoundTag&gt; getResult(ServerLevel level)</code> (returns hit state &amp; NBT when random roll &lt;= <code>chance</code>, else <code>null</code>).</li></ul><h3 id="_3-weightedchanceblockstates-list-entry-states" tabindex="-1">3. <code>WeightedChanceBlockStates(List&lt;Entry&gt; states)</code> <a class="header-anchor" href="#_3-weightedchanceblockstates-list-entry-states" aria-label="Permalink to &quot;3. `WeightedChanceBlockStates(List&lt;Entry&gt; states)`&quot;">​</a></h3><p>Selects a probabilistic block outcome from a weighted list, built via <code>WeightedChanceBlockStates.builder()</code>:</p><ul><li><code>add(...)</code> provides rich overloads taking weight <code>NumberProvider</code> / <code>float</code>, target <code>BlockState</code> / <code>Block</code> / <code>Supplier&lt;? extends Block&gt;</code>, optional <code>CompoundTag</code>, and output chance <code>NumberProvider</code> / <code>float</code>;</li><li><code>isEmpty()</code> checks if any entries exist, <code>build()</code> constructs it, and <code>getResult(ServerLevel)</code> performs weighted selection and chance rolling.</li></ul>',24)])])}const p=t(d,[["render",i]]);export{m as __pageData,p as default};
